mapper.select:
SELECT balance
FROM deposit_account
WHERE user_id = #{userId}

SELECT
    COALESCE(SUM(CASE WHEN txn_type = 1 THEN amount ELSE 0 END), 0) AS income,
    COALESCE(SUM(CASE WHEN txn_type = 0 AND merchant_name != '정기적금이체' THEN amount ELSE 0 END), 0) AS expense
FROM transaction
WHERE user_id = #{userId}
  AND DATE_FORMAT(txn_date, '%Y-%m') = #{yearMonth}

SELECT closing_balance
FROM report_balance_snapshot
WHERE user_id = #{userId} AND `year_month` = #{yearMonth}
